from flask import Flask, jsonify, abort

app = Flask(__name__)

# Example student records
students = {
    1: {'name': 'Alice', 'age': 20, 'major': 'Computer Science'},
    2: {'name': 'Bob', 'age': 22, 'major': 'Mathematics'},
    3: {'name': 'Charlie', 'age': 21, 'major': 'Physics'}
