    }

    // Getter for the balance
    public double getBalance() {
        return balance;
    }

    // Setter for the balance with validation to prevent negative balance
    public void setBalance(double newBalance) {
        if (newBalance >= 0) {
            this.balance = newBalance;
        } else {
            System.out.println("Error: Cannot set a negative balance.");
        }
    }

    // Method to deposit money into the account
    public void deposit(double amount) {
        if (amount > 0) {
            this.balance += amount;
        } else {
            System.out.println("Error: Cannot deposit a negative amount.");
        }
    }

    // Method to withdraw money from the account
    public void withdraw(double amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
        } else {
            System.out.println("Error: Cannot withdraw a negative amount or more than the current balance.");
        }
    }
}
```

